INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('cai-huanhou','蔡桓侯','zhou-east','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','《韩非子·喻老》中的“蔡桓公”是扁鹊故事人物，故事以病情由浅入深而拒绝治疗，说明讳疾忌医的后果；不能单凭寓言确认其为蔡国某位真实君主。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/蔡桓侯"},{"label":"《韩非子·喻老》（中国哲学书电子化计划）","url":"https://ctext.org/hanfeizi/yu-lao/zh"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('cao-gui','曹刿','lu-chunqiu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','春秋鲁国人，事迹主要见于《左传·庄公十年》。齐鲁长勺之战前，他向鲁庄公陈说取信于民、审时用兵之理；战后以“一鼓作气”解释待齐军疲惫再追击的战术。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曹刿"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('cheng-yi','程颐','song-north','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["思想家"]','北宋理学家，字正叔，河南洛阳人，与兄程颢并称“二程”。师从周敦颐，讲学洛阳，强调格物穷理；其学说由门人记录，成为程朱理学的重要源头。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/程颐"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('feng-xuan','冯谖','qi-chunqiu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','战国齐国人，孟尝君田文门客。曾为孟尝君赴薛收债，焚券市义；返齐后以“狡兔三窟”劝其经营退路，帮助巩固封邑与政治地位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/冯谖"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('geng-ying','更羸','wei-warring','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家"]','战国魏国善射者，事迹见《战国策·楚策四》。他向魏王展示弓术，凭空弦声使受伤的飞鸟坠落，“惊弓之鸟”遂成为典故；其生平细节少见于史籍。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/更羸"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jing-ke','荆轲','yan-chunqiu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["刺客"]','战国末卫国人，后游历燕地，受燕太子丹礼遇。前227年奉命携督亢地图入秦，行刺秦王政未遂而死；相关叙事见《史记·刺客列传》，后世广泛传为荆轲刺秦王。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/荆轲"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('lian-po','廉颇','zhao-warring','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家"]','赵国名将，长平战前主将，负荆请罪与蔺相如释怨；赵王中反间计后以赵括代其为将，赵军长平战败；廉颇晚年客居魏、楚。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/廉颇"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('lin-xiangru','蔺相如','zhao-warring','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','赵国名臣，完璧归赵、渑池之会，与廉颇将相和；赴秦交涉和氏璧、渑池之会时维护赵国尊严；与廉颇化解嫌隙后被称“将相和”。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/蔺相如"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('mao-sui','毛遂','zhao-warring','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','战国赵国平原君门客。秦围邯郸时，他自荐随平原君赴楚求援，在楚廷陈说利害、促成合纵盟约；“毛遂自荐”由此成为典故。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/毛遂"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('pang-chong','庞葱','wei-warring','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','魏国大臣，太子傅，赴邯郸前以三人成虎谏魏王；“ 三人成虎”典故出自《战国策·魏策》，用来说明传言可能因反复传播而被误信。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/庞葱"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('shen-zhuliang','沈诸梁','chu-chunqiu','["叶公"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','春秋末楚国大夫，封于叶，称叶公。曾参与平定白公胜之乱；“叶公好龙”出自刘向《新序》等后世故事，故事中的叶公形象不宜直接等同其完整生平。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/叶公"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('tian-wen','田文','qi-chunqiu','["孟尝君"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','战国齐国宗室，齐威王之孙，封于薛，号孟尝君。广招门客，以善养士著称；曾任齐相并参与合纵，后历仕秦、魏，政治经历随诸侯局势多次变化。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/孟尝君"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-ying','晏婴','qi-chunqiu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','齐国名相，辅佐齐景公；二桃杀三士等事与其相关；他以节俭、善谏和外交辞令闻名，相关言行主要由《晏子春秋》保存。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/晏婴"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yang-shi','杨时','song-north','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["思想家"]','北宋学者，字中立，福建将乐人，早年从程颢、程颐问学，后长期讲学并任地方官。程门立雪故事记其与游酢拜访程颐、立雪候教，体现后世对其尊师求学的推重。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杨时"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhang-sengyou','张僧繇','liang-nan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["画家"]','南北朝画家，安乐寺画龙点睛传说与其相关；安乐寺画龙点睛故事见唐代《历代名画记》，属于后世传说，画家真迹今已不存。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/张僧繇"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhao-sheng','赵胜','zhao-warring','["平原君"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','战国赵国宗室，赵武灵王之子，封平原君，以礼贤养士闻名。秦围邯郸时组织守城并赴楚求援，门客毛遂随行促成楚赵合纵；与孟尝君、信陵君、春申君并称战国四公子。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/平原君"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhao-zhuo','赵括','zhao-warring','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家"]','战国赵国将领，赵奢之子。长平之战中接替廉颇为主将，改变守势后遭秦军包围；赵括率精锐突围时中秦军射杀，赵军余部随后投降并遭坑杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赵括"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhuang-xin','庄辛','chu-chunqiu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','战国楚国大夫，曾任谏官。楚顷襄王亲近佞臣、疏远贤者时，庄辛以“亡羊补牢”等譬喻劝谏；故事见《战国策·楚策》，具体言行带有策士文学色彩。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/庄辛"}]',NULL,NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('idiom-ai-wu-ji-wu','爱屋及乌','idiom','point','year',NULL,NULL,'武王克商前后，前1046年；典出《尚书大传·牧誓》',-1046,12,NULL,-12529,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'《尚书大传·牧誓》载太公说爱人者兼其屋上之乌，后凝结为成语。','比喻爱一个人而连带喜爱与他有关的人或物。',NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('idiom-bei-shui-yi-zhan','背水一战','idiom','point','year',NULL,NULL,'井陉之战',-204,12,NULL,-2425,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'韩信井陉背水列阵，大破赵军。','比喻没有退路，只能决一死战。',NULL,'[]');
