INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('idiom-cheng-men-li-xue','程门立雪','idiom','point','year',NULL,NULL,NULL,1080,12,NULL,12971,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'杨时、游酢候程颐于门外，雪深没膝而不敢惊动。','比喻尊敬师长，虔诚求学。',NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('idiom-cheng-ye-xiao-he','成也萧何败也萧何','idiom','point','year',NULL,NULL,NULL,-196,12,NULL,-2329,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'韩信由萧何举荐而兴，又因萧何入未央宫被害。','比喻事情的成功或失败都出于同一个人或同一原因。',NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('idiom-chun-wang-chi-han','唇亡齿寒','idiom','point','year',NULL,NULL,'晋献公借道伐虢，前655年',-655,12,NULL,-7837,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'宫之奇谏虞公：「唇亡齿寒，虞、虢之表也。」晋借道伐虢后灭虞。','比喻利害密切相关，一方受损另一方也难保全。',NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('idiom-dao-lu-yi-mu','道路以目','idiom','point','year',NULL,NULL,'国人暴动前',-841,12,NULL,-10069,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'周厉王专利暴虐，国人不敢言，道路相遇仅以目示意。','形容严酷统治下，人们不敢交谈，路上相遇只以目示意。',NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('idiom-dong-shi-xiao-pin','东施效颦','idiom','point','year',NULL,NULL,'庄子寓言',-320,12,NULL,-3817,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'《庄子》东施效西施之颦，邻人闭户不出，见其丑态。','比喻盲目模仿别人，不但学不像，反而出丑。',NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('idiom-dui-niu-tan-qin','对牛弹琴','idiom','point','year',NULL,NULL,'庄子寓言，一说出自牟子',-320,12,NULL,-3817,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'《庄子》公明仪为牛弹清角之操，牛食如故，非牛不闻，不合其耳。','比喻对不能理解的人讲道理，白费口舌。',NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('idiom-duo-duo-yi-shan','多多益善','idiom','point','year',NULL,NULL,NULL,-202,12,NULL,-2401,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'汉高祖问韩信能带多少兵，韩信答「臣，多多益善」。','形容越多越好。',NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('idiom-duo-xing-bu-yi-bi-zi-bi','多行不义必自毙','idiom','point','year',NULL,NULL,'郑庄公克段，前701年',-701,12,NULL,-8389,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'《左传》郑伯克段于鄢，公曰：「多行不义必自毙，子姑待之。」','坏事干得多了，必定会自取灭亡。',NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('idiom-er-tao-sha-san-shi','二桃杀三士','idiom','point','year',NULL,NULL,'齐景公时，约前522年',-522,12,NULL,-6241,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'晏婴献二桃，公孙接、田开疆、古冶子争功，后二人自杀，古冶子亦自刎。','比喻用阴谋借刀杀人，或借小事除掉强者。',NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('idiom-fen-dao-yang-biao','分道扬镳','idiom','point','year',NULL,NULL,'北魏孝文帝迁都洛阳后，约493年；典出《北史》',493,12,NULL,5927,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'北魏孝文帝迁都洛阳后，洛阳令元志与御史中尉李彪争道，孝文帝命二人分路而行。','比喻目标不同，各走各的路；也指分道而行。',NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('idiom-feng-lang-ju-xu','封狼居胥','idiom','point','year',NULL,NULL,'元狩四年，前119年；典出《史记·卫将军骠骑列传》及《汉书·卫青霍去病传》',-119,12,NULL,-1405,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'汉武帝元狩四年（前119年），霍去病率军深入漠北击败匈奴左部，登狼居胥山祭天、于姑衍山祭地后返师。后世以“封狼居胥”概括这一战功，成为建功边疆的典故。','比喻建立显赫战功，常用来形容将领远征并取得重大胜利。',NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('idiom-fu-jing-qing-zui','负荆请罪','idiom','point','year',NULL,NULL,'渑池之会后将相和，约前279年',-279,12,NULL,-3325,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'廉颇闻蔺相如避让之由，负荆请罪，二人结为刎颈之交。','形容主动认错、道歉，请求责罚。',NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('idiom-gang-zheng-bu-a','刚正不阿','idiom','point','year',NULL,NULL,'嘉靖四十五年',1565,12,NULL,18791,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'海瑞上《治安疏》骂嘉靖，以刚直闻名。','刚强正直，不逢迎，无偏私。',NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('idiom-handan-xue-bu','邯郸学步','idiom','point','year',NULL,NULL,'庄子寓言',-300,12,NULL,-3577,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'《庄子》燕国少年学赵都邯郸之步，未能得能，又失其故步，匍匐而归。','比喻模仿别人不成，反而失去自己原有的技能。',NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('idiom-hu-fu-qi-she','胡服骑射','idiom','point','year',NULL,NULL,'赵武灵王十九年，前307年；《史记·赵世家》记其下令招骑射并议胡服。',-307,12,NULL,-3661,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'战国时赵武灵王面对北方游牧势力与中山国的威胁，决定改穿便于骑乘的胡服并训练骑射。赵国贵族公子成起初反对，武灵王亲自劝说后推行改革，增强了赵军机动能力，为此后北拓和攻取中山奠定基础。','指改穿便于骑射的胡服、学习骑马射箭；后用以比喻改革旧制，吸收他人所长以增强实力。',NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('idiom-hu-jia-hu-wei','狐假虎威','idiom','point','year',NULL,NULL,'《战国策·楚策》楚宣王问江乙时所举寓言',-275,12,NULL,-3277,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'《战国策·楚策》载楚宣王问江乙，江乙以虎狐同行、百兽皆走为喻。','比喻倚仗别人的势力欺压人。',NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('idiom-hua-long-dian-jing','画龙点睛','idiom','point','year',NULL,NULL,'梁陈间事，成语通行于唐',550,12,NULL,6611,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'张僧繇在金陵安乐寺画龙，点睛后龙破壁飞去。','比喻说话或写作在关键处点明要旨，使内容生动传神。',NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('idiom-hua-she-tian-zu','画蛇添足','idiom','point','year',NULL,NULL,'战国策寓言',-280,12,NULL,-3337,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'《战国策》楚人画蛇，先成者添足，酒不得饮。','比喻做了多余的事，反而把事情弄坏。',NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('idiom-hui-ji-ji-yi','讳疾忌医','idiom','point','year',NULL,NULL,'《韩非子》载扁鹊见蔡桓侯，战国寓言',-400,12,NULL,-4777,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'蔡桓侯讳疾忌医，扁鹊每见病深一层，终不可救。','比喻隐瞒缺点，拒绝批评和帮助。',NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('idiom-jia-dao-fa-guo','假道伐虢','idiom','point','year',NULL,NULL,'晋灭虢，前655年；《左传》记鲁僖公五年。',-655,12,NULL,-7837,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'晋献公先以讨伐虢国为名向虞国借道，灭虢后回师袭灭虞国。《左传·僖公二年、五年》记载了这两次借道与宫之奇的劝谏。','以借路为名，行灭亡对方之实；后用来比喻利用对方作为进攻第三方的通道，达到目的后再消灭对方。',NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('idiom-jiao-tu-san-ku','狡兔三窟','idiom','point','year',NULL,NULL,'冯谖谏孟尝君，战国',-300,12,NULL,-3577,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'《战国策》冯谖谓孟尝君：狡兔有三窟，仅得免其死耳。','比喻隐蔽的地方多，便于藏身或留有退路。',NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('idiom-jing-di-zhi-wa','井底之蛙','idiom','point','year',NULL,NULL,'庄子寓言',-320,12,NULL,-3817,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'《庄子》井蛙不可以语于海者，拘于虚也。','比喻见识狭窄、眼光短浅的人。',NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('idiom-jing-gong-zhi-niao','惊弓之鸟','idiom','point','year',NULL,NULL,'战国策寓言，约前251年',-251,12,NULL,-2989,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'《战国策》更羸与魏王处京台，引弓虚发，雁坠，盖其伤弓未愈。','比喻受过惊吓的人遇到类似情形就惶恐不安。',NULL,'[]');
