INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('idiom-mai-du-huan-zhu','买椟还珠','idiom','point','year',NULL,NULL,'韩非子寓言',-275,12,NULL,-3277,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'《韩非子》楚人卖珠于郑，椟饰以木兰、薰以桂椒，郑人买其椟而还其珠。','比喻取舍不当，舍本逐末；也指不识货。',NULL,'[]');
