INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('idiom-nan-yuan-bei-zhe','南辕北辙','idiom','point','year',NULL,NULL,'战国策寓言',-310,12,NULL,-3697,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'《战国策》有人欲之楚而北行，马良、用多、御善，愈善而离楚愈远。','比喻行动和目的相反，越努力离目标越远。',NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('idiom-po-fu-chen-zhou','破釜沉舟','idiom','point','year',NULL,NULL,'巨鹿之战前后',-207,12,NULL,-2461,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'项羽渡漳水后破釜沉舟，只带三日粮，大破秦军于巨鹿。','比喻下定决心，不顾一切地干到底。',NULL,'[]');
