INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('idiom-zhu-zhou-wei-nue','助纣为虐','idiom','point','year',NULL,NULL,'牧野克商前后',-1046,12,NULL,-12529,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'比干谏纣王被杀，后世以「助纣为虐」喻帮凶为恶。','比喻帮助坏人干坏事。',NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('idiom-zi-xiang-mao-dun','自相矛盾','idiom','point','year',NULL,NULL,'韩非子寓言',-280,12,NULL,-3337,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'《韩非子》楚人鬻盾与矛，誉盾坚莫能陷、矛利无不陷，或曰以矛陷盾，弗能应。','比喻言行前后抵触，不能自圆其说。',NULL,'[]');
